data.transform:
(
  /* Calculate previous hour in UTC */
  $prevHourStart := $moment().startOf('hour').subtract(1, 'hour');
  $prevHourEnd := $moment($prevHourStart).add(1, 'hour');
  
  /* Output UTC time window */
  {
    "periodStart": $moment($prevHourStart),
    "periodEnd": $moment($prevHourEnd),
    "periodAt": $moment($prevHourStart),
    "utcHour": $moment($prevHourStart).format("YYYY-MM-DD HH:00")
  }
)

data.query:
query GetDataPointsForAggregation {
  dataPoint(
    where: {
      enabled: { _eq: true }
      historize: { _eq: true }
    }
    first: 100000
  ) {
    edges {
      node {
        id
        code
        dataType
        unitId
      }
    }
  }
}

data.transform:
/**
 * Batch DataPoints for Aggregation
 * Pure UTC - No Timezone Handling
 * 
 * INPUT: 
 *   $ (payload): DataPoint query result
 *   $state.context.timeWindow: { periodStart, periodEnd, periodAt }
 * 
 * OUTPUT: 
 *   Array of batch objects for broadcast
 */

'use strict';

var batchSize = 100;

var timeWindow = ($state && $state.context && $state.context.timeWindow) || {};
var periodStart = timeWindow.periodStart;
var periodEnd = timeWindow.periodEnd;
var periodAt = timeWindow.periodAt;

if (!periodAt) {
  console.error('ERROR: timeWindow not found in context');
  return null;
}

console.log('Aggregation Window (UTC): ' + periodStart + ' to ' + periodEnd);

// Extract and group dataPoints by type
var edges = ($ && $.dataPoint && $.dataPoint.edges) || [];
var numericPoints = [];
var booleanPoints = [];

for (var i = 0; i < edges.length; i++) {
  var node = edges[i].node;
  if (!node || !node.id) continue;
  
  var dataType = (node.dataType || '').toLowerCase();
  var dp = {
    id: node.id,
    code: node.code,
    unitId: node.unitId
  };
  
  if (dataType === 'float' || dataType === 'integer') {
    numericPoints.push(dp);
  } else if (dataType === 'boolean') {
    booleanPoints.push(dp);
  }
}

console.log('DataPoints: ' + numericPoints.length + ' numeric, ' + booleanPoints.length + ' boolean');

// Create batches
function createBatches(dataPoints, dataType) {
  var batches = [];
  if (!dataPoints || dataPoints.length === 0) return batches;
  
  var totalBatches = Math.ceil(dataPoints.length / batchSize);
  
  for (var i = 0; i < dataPoints.length; i += batchSize) {
    var batch = dataPoints.slice(i, i + batchSize);
    batches.push({
      dataPoints: batch,
      dataPointIds: batch.map(function(dp) { return dp.id; }),
      periodStart: periodStart,
      periodEnd: periodEnd,
      periodAt: periodAt,
      batchIndex: Math.floor(i / batchSize) + 1,
      totalBatches: totalBatches,
      dataType: dataType,
      count: batch.length
    });
  }
  
  return batches;
}

var allBatches = createBatches(numericPoints, 'numeric')
  .concat(createBatches(booleanPoints, 'boolean'));

console.log('Created ' + allBatches.length + ' batches (' + batchSize + ' dataPoints each)');

if (allBatches.length === 0) {
  console.log('No DataPoints to aggregate');
  return null;
}

return allBatches;

data.query:
query TelemetryRaw($where: TelemetryRawWhereInput, $orderBy: [TelemetryRawOrderByInput!], $first: Int, $after: String) {
  telemetryRaw(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        dataPointId
        _aggregate {
          value {
            count
            minimum
            maximum
            average
            sum
            first
            last
            standardDeviation
            median
            uniqueCount
            percentile(percentiles: [5, 25, 50, 75, 95])
           
          }
        }
      }
    }
  }
}

data.variablesTransform:
$count($.telemetryRaw.edges) > 0 ? {
  "payload": $.telemetryRaw.edges.{
    "create": {
      "dataPointId": node.dataPointId,
      "periodAt": $state.context.timeWindow.periodAt,
      "count": node._aggregate.value.count,
      "distinctCount": node._aggregate.value.uniqueCount,
      "min": node._aggregate.value.minimum[0],
      "max": node._aggregate.value.maximum[0],
      "avg": node._aggregate.value.average,
      "sum": node._aggregate.value.sum,
      "std": node._aggregate.value.standardDeviation,
      "first": node._aggregate.value.first[0],
      "last": node._aggregate.value.last[0],
      "p05": node._aggregate.value.percentile[0],
      "p25": node._aggregate.value.percentile[1],
      "p50": node._aggregate.value.percentile[2],
      "p75": node._aggregate.value.percentile[3],
      "p95": node._aggregate.value.percentile[4]
    }
  }
} : {
  "payload": []
}

data.mutation:
mutation CreateTelemetryHourly($payload: [TelemetryHourlyCreatePayloadInput!]!) {
  createTelemetryHourly(payload: $payload) {
    id
    dataPointId
    periodAt
    count
  }
}

